    for col in range(4, 7):
        grid_final[row][col] = 6

# 0s: horizontal arm at row 13 cols 16-19, vertical at col 16 rows 13-19
for col in range(16, 20):
    grid_final[13][col] = 0
for row in range(13, 20):
    grid_final[row][16] = 0

# 4s: T shape at rows 15-19 cols 18-22 (hole at row 18, col 20)
for row in range(15, 20):
    for col in range(18, 23):
        grid_final[row][col] = 4
grid_final[18][20] = 3  # hole

print("Output grid:")
for row in grid_final:
    print(" ".join(map(str, row)))

